const assert=require('node:assert/strict');
const vm=require('node:vm'),fs=require('node:fs'),path=require('node:path');
const api=require('./scoreboard-mutation-v2.js');
const map=new Map();const storage={getItem:k=>map.get(k)||null,setItem:(k,v)=>map.set(k,v)};
const context={ScoreboardMutationV2:api,localStorage:storage,crypto:{randomUUID:(()=>{let n=0;return()=>String(++n)})()},Date,JSON,Set,Array,Error,console};
vm.runInNewContext(fs.readFileSync(path.join(__dirname,'scoreboard-v2-sync.js'),'utf8'),context);
const q=context.ScoreboardV2Sync;
q.setAccount('userA');
const one=q.enqueue('add','record','r1',{points:1});
const two=q.enqueue('delete','record','r2',{points:2});
const fixed=q.batch();assert.equal(fixed.mutations.length,2);assert.deepEqual(Array.from(fixed.mutationIds),[one.mutationId,two.mutationId]);
q.enqueue('add','record','r3',{points:3});assert.equal(q.batch().mutationIds.length,2,'batch snapshot stays fixed');
assert.deepEqual(Array.from(q.acknowledge([one.mutationId])),[one.mutationId]);assert.equal(q.batch().mutationIds.length,1,'partial ACK leaves remainder');
q.markUnknown([two.mutationId]);assert.equal(q.retryUnknown([two.mutationId]).length,1,'UNKNOWN is retryable');
q.setAccount('userB');assert.equal(q.batch(),null,'account B cannot see account A batch');
q.setAccount('userA');assert.equal(q.pending().length,2,'account A pending remains isolated');
const reset=q.resetIntent();assert.equal(reset.targetEpoch,1);
assert.throws(()=>q.resetIntent(),/Reset already pending/);
q.confirmReset(reset.resetRequestId);assert.equal(q.read().epoch,1);assert.equal(q.pending().length,0);
q.enqueue('add','record','new',{points:1});assert.equal(q.pending()[0].resetEpoch,1);
console.log('Scoreboard V2 adapter tests PASS');
